#!/usr/bin/env python3
import json, os

with open("input.json") as f:
    inp = json.load(f)

issues = inp.get("issues", [])
repo_path = inp.get("repo_path")
if not repo_path:
    print(json.dumps({"issues": [], "files": [], "error": "repo_path missing from git-clone output"}))
    raise SystemExit(1)
max_files = int(inp.get("max_files", 1))
max_issues = int(inp.get("max_issues", 2))
max_chars = int(inp.get("max_chars_per_file", 12000))

generated_path_markers = (
    "/flinkclient", "/nextbreakpoint/", "/generated/", "/target/",
)
generated_content_markers = (
    "auto generated", "swagger codegen", "do not edit the class manually",
)

def is_generated_path(path):
    lower = "/" + path.lower()
    return any(marker in lower for marker in generated_path_markers)

candidates = []
selected = []
for issue in issues:
    fp = issue.get("file", "")
    if not fp or is_generated_path(fp):
        continue
    full = os.path.join(repo_path, fp)
    if not os.path.isfile(full):
        continue
    with open(full, errors="replace") as f:
        sample = f.read(2048).lower()
    if any(marker in sample for marker in generated_content_markers):
        continue
    candidates.append((os.path.getsize(full), fp, full, issue))

if not candidates:
    for issue in issues:
        fp = issue.get("file", "")
        if not fp:
            continue
        full = os.path.join(repo_path, fp)
        if os.path.isfile(full):
            candidates.append((os.path.getsize(full), fp, full, issue))

files = {}
selected_file_paths = set()
for _, fp, full, issue in sorted(candidates, key=lambda item: item[0]):
    if len(files) >= max_files and fp not in selected_file_paths:
        continue
    if full not in files and len(files) < max_files:
        with open(full, errors="replace") as f:
            content = f.read(max_chars + 1)
        files[full] = {
            "path": fp,
            "content": content[:max_chars],
            "truncated": len(content) > max_chars,
            "size": os.path.getsize(full),
        }
        selected_file_paths.add(fp)
    if fp in selected_file_paths and len(selected) < max_issues:
        selected.append(issue)
    if len(files) >= max_files and len(selected) >= max_issues:
        break

result = {
    "issues": selected,
    "files": list(files.values()),
    "selection": {
        "issue_count": len(selected),
        "file_count": len(files),
        "max_chars_per_file": max_chars,
    },
}
print(json.dumps(result))

